"""Generate the rule catalog from diagnostic metadata; keep detailed guides curated."""

import argparse
from pathlib import Path

from torchlight.diagnostics import RULES

ROOT = Path(__file__).resolve().parents[1]


def catalog() -> str:
    lines = [
        "<!-- Generated by python -m scripts.generate_rule_docs; do not edit. -->",
        "# Rule catalog",
        "",
        "All current rules emit warnings and have no automatic fix. A finding is a",
        "review request, not proof of a failure. Spark-version targeting and measured",
        "confidence tiers are not implemented.",
        "",
        "| ID | Review topic |",
        "| --- | --- |",
    ]
    for code, rule in RULES.items():
        lines.append(f"| [{code}]({code}.md) | {rule.title} |")
    for code, rule in RULES.items():
        lines.extend(
            [
                "",
                f"## {code}: {rule.title}",
                "",
                rule.explanation,
                "",
                f"**Review:** {rule.recommendation}",
                "",
                f"[Examples, evidence, and limitations]({code}.md).",
            ]
        )
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="Fail if the catalog is stale."
    )
    args = parser.parse_args()
    path = ROOT / "docs" / "rules" / "README.md"
    expected = catalog()
    if args.check:
        if not path.is_file() or path.read_text(encoding="utf-8") != expected:
            raise SystemExit(
                "Rule catalog is stale; run python -m scripts.generate_rule_docs"
            )
        for code in RULES:
            if not (path.parent / f"{code}.md").is_file():
                raise SystemExit(f"Missing curated rule guide: {code}.md")
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(expected, encoding="utf-8")


if __name__ == "__main__":
    main()
